'use client';

import React, { useState, useMemo } from 'react';
import { usePOS } from '@/modules/pos/context/POSContext';
import { useRouter } from 'next/navigation';
import {
    Search,
    ShoppingCart,
    ChevronRight,
    Plus,
    Minus,
    Trash2,
    Clock,
    ArrowRight,
    Search as SearchIcon,
    Scan,
    Info,
    Star,
    Leaf,
    Flame,
    Check,
    X,
    Pause,
    Tag,
    Settings as SettingsIcon,
    AlertCircle,
    ChevronDown
} from 'lucide-react';
import { mockPOSProducts, mockPOSCategories } from '../mock/posData';
import { POSProduct, POSCartItem, OrderChannel, POSVariantGroup, POSModifierGroup, POSComboSlot } from '../types/pos';
import { formatCurrency } from '@/utils';
import { POSDiscountModal } from '../components/POSDiscountModal';
import { POSQuickSettings } from '../components/POSQuickSettings';

export const POSMenuScreen: React.FC = () => {
    const { session, setCustomer, cart, setCart } = usePOS();
    const [activeCategory, setActiveCategory] = useState<string>(mockPOSCategories[0].id);
    const [searchQuery, setSearchQuery] = useState('');
    const [activeTab, setActiveTab] = useState<'ALL' | 'FAVORITES' | 'TOP' | 'HOLD'>('ALL');
    const [selectedProduct, setSelectedProduct] = useState<POSProduct | null>(null);
    const [showSuccess, setShowSuccess] = useState(false);
    const [showDiscountModal, setShowDiscountModal] = useState(false);
    const [showQuickSettings, setShowQuickSettings] = useState(false);
    const [appliedDiscount, setAppliedDiscount] = useState<number>(0);
    const [orderType, setOrderType] = useState<OrderChannel>('Dine-In');

    // Customization State
    const [selectedVariants, setSelectedVariants] = useState<{ [groupId: string]: string }>({});
    const [selectedModifiers, setSelectedModifiers] = useState<{ [optionId: string]: { name: string; price: number; quantity: number } }>({});
    const [comboSelections, setComboSelections] = useState<{ [slotId: string]: POSCartItem }>({});
    const [activeComboSlot, setActiveComboSlot] = useState<string | null>(null);

    const router = useRouter();

    // Filter products
    const filteredProducts = mockPOSProducts.filter(p =>
        (p.categoryId === activeCategory || activeCategory === 'all') &&
        (p.name.toLowerCase().includes(searchQuery.toLowerCase()) || p.sku.toLowerCase().includes(searchQuery.toLowerCase()))
    );

    const handleProductClick = (product: POSProduct) => {
        if (product.hasVariants || product.isCombo || (product.modifierGroups && product.modifierGroups.length > 0)) {
            setSelectedProduct(product);
            // Initialize defaults
            const initialVariants: { [key: string]: string } = {};
            product.variantGroups?.forEach(group => {
                initialVariants[group.id] = group.options[0].id;
            });
            setSelectedVariants(initialVariants);
            setSelectedModifiers({});
            setComboSelections({});
            if (product.isCombo && product.comboSlots) {
                setActiveComboSlot(product.comboSlots[0].id);
            } else {
                setActiveComboSlot(null);
            }
        } else {
            addToCart(product);
        }
    };

    const addToCart = (product: POSProduct, customizedData?: Partial<POSCartItem>) => {
        const item: POSCartItem = {
            id: Math.random().toString(36).substr(2, 9),
            productId: product.id,
            name: product.name,
            price: customizedData?.price ?? product.price,
            quantity: 1,
            variants: customizedData?.variants ?? [],
            modifiers: customizedData?.modifiers ?? [],
            comboSelections: customizedData?.comboSelections
        };
        setCart([...(cart || []), item]);
    };

    const updateQuantity = (id: string, delta: number) => {
        setCart(cart?.map(item => {
            if (item.id === id) {
                const newQty = Math.max(1, item.quantity + delta);
                return { ...item, quantity: newQty };
            }
            return item;
        }) || []);
    };

    const removeFromCart = (id: string) => {
        setCart(cart?.filter(item => item.id !== id) || []);
    };

    const subtotal = cart?.reduce((acc, item) => acc + (item.price * item.quantity), 0) || 0;
    const discountAmount = appliedDiscount > 0 ? (appliedDiscount < 1 ? subtotal * appliedDiscount : appliedDiscount) : 0;
    const tax = (subtotal - discountAmount) * 0.1;
    const total = subtotal - discountAmount + tax;

    // Customization logic
    const currentCustomPrice = useMemo(() => {
        if (!selectedProduct) return 0;
        let base = selectedProduct.price;
        // Variants
        Object.entries(selectedVariants).forEach(([groupId, optionId]) => {
            const group = selectedProduct.variantGroups?.find(g => g.id === groupId);
            const option = group?.options.find(o => o.id === optionId);
            if (option) base += option.additionalPrice;
        });
        // Modifiers
        Object.values(selectedModifiers).forEach(mod => {
            base += mod.price * mod.quantity;
        });
        // Combo selections (if any paid additions)
        Object.values(comboSelections).forEach(sel => {
            // Usually combos have fixed price, but individual items might have upcharges
            // For now assume combo price is fixed p6 price
        });
        return base;
    }, [selectedProduct, selectedVariants, selectedModifiers, comboSelections]);

    const handleAddCustomized = () => {
        if (!selectedProduct) return;

        const variantsArr = Object.entries(selectedVariants).map(([groupId, optionId]) => {
            const group = selectedProduct.variantGroups?.find(g => g.id === groupId);
            const option = group?.options.find(o => o.id === optionId);
            return { groupId, optionId, name: option?.name || '' };
        });

        const modifiersArr = Object.entries(selectedModifiers).map(([optionId, data]) => ({
            optionId,
            ...data
        }));

        addToCart(selectedProduct, {
            price: currentCustomPrice,
            variants: variantsArr,
            modifiers: modifiersArr,
            comboSelections: selectedProduct.isCombo ? comboSelections : undefined
        });
        setSelectedProduct(null);
    };

    return (
        <div className="flex h-screen bg-white text-brand font-sans overflow-hidden">
            {/* LEFT: CATEGORIES PANEL (Section 7) */}
            <aside className="w-24 md:w-32 bg-brand/5 border-r border-brand/10 flex flex-col items-center py-6 gap-2 flex-shrink-0 overflow-y-auto custom-scrollbar">
                <button
                    onClick={() => setActiveCategory('all')}
                    className={`w-16 h-16 md:w-20 md:h-20 rounded-2xl flex flex-col items-center justify-center gap-1 transition-all ${activeCategory === 'all' ? 'bg-brand text-white shadow-lg shadow-brand/20' : 'text-brand/40 hover:bg-brand/10 hover:text-brand'}`}
                >
                    <div className="text-[10px] font-black uppercase tracking-widest">All</div>
                </button>
                {mockPOSCategories.map(cat => (
                    <button
                        key={cat.id}
                        onClick={() => setActiveCategory(cat.id)}
                        className={`w-16 h-16 md:w-20 md:h-20 rounded-2xl flex flex-col items-center justify-center gap-1 transition-all p-2 text-center ${activeCategory === cat.id ? 'bg-brand text-white shadow-lg shadow-brand/20' : 'text-brand/40 hover:bg-brand/10 hover:text-brand'}`}
                    >
                        <span className="text-[10px] font-black uppercase tracking-tight leading-tight">{cat.name}</span>
                    </button>
                ))}
            </aside>

            {/* CENTER: PRODUCTS GRID (Section 7) */}
            <main className="flex-1 flex flex-col min-w-0 bg-[#F1F5F9]">
                {/* Top Tabs (Image 5) */}
                <div className="bg-brand px-6 pt-2 flex items-center justify-between min-h-[56px] flex-shrink-0">
                    <div className="flex items-center gap-1 h-full">
                        {[
                            { id: 'ALL', label: 'All Items' },
                            { id: 'FAVORITES', label: 'Favorites' },
                            { id: 'TOP', label: 'Top Items' },
                            { id: 'HOLD', label: 'On Hold' }
                        ].map(tab => (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id as any)}
                                className={`px-6 py-3 rounded-t-xl text-[10px] font-black uppercase tracking-widest transition-all h-full flex items-center ${activeTab === tab.id ? 'bg-[#F1F5F9] text-brand' : 'text-white/60 hover:text-white'}`}
                            >
                                {tab.label}
                            </button>
                        ))}
                    </div>

                    <div className="flex items-center gap-4">
                        <div className="hidden lg:flex items-center gap-2 px-3 py-1 bg-white/10 rounded-lg backdrop-blur-md">
                            <AlertCircle size={14} className="text-amber-400" />
                            <span className="text-[9px] font-black text-white uppercase tracking-widest">Pricing: Weekend Special (1.2x)</span>
                        </div>
                        <button
                            onClick={() => setShowQuickSettings(true)}
                            className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center text-white/80 hover:text-white transition-all backdrop-blur-md"
                        >
                            <SettingsIcon size={18} />
                        </button>
                    </div>
                </div>

                {/* Search & Tool Bar */}
                <header className="h-16 bg-white border-b border-brand/5 px-6 flex items-center justify-between gap-6 flex-shrink-0">
                    <div className="flex-1 relative">
                        <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-brand/30" size={18} />
                        <input
                            type="text"
                            placeholder="Search by Name / SKU / Barcode"
                            className="w-full h-10 bg-[#F1F5F9] rounded-lg pl-12 pr-6 text-sm font-medium border-transparent focus:bg-white focus:border-brand/20 outline-none transition-all"
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                    </div>
                </header>

                {/* Product Grid */}
                <div className="flex-1 overflow-y-auto p-6 grid grid-cols-2 lg:grid-cols-4 gap-4 custom-scrollbar">
                    {filteredProducts.map(product => (
                        <button
                            key={product.id}
                            onClick={() => handleProductClick(product)}
                            className="bg-white border border-brand/5 rounded-xl p-3 flex flex-col group transition-all hover:ring-2 hover:ring-brand shadow-sm active:scale-95 text-left relative overflow-hidden h-fit"
                        >
                            <div className="aspect-[4/3] bg-brand/5 rounded-lg mb-3 overflow-hidden relative">
                                <img src={product.image} alt={product.name} className="w-full h-full object-cover" />
                                <div className="absolute top-2 right-2 flex gap-1">
                                    {product.isVeg ? (
                                        <div className="w-4 h-4 bg-white border border-emerald-500 flex items-center justify-center p-0.5">
                                            <div className="w-full h-full bg-emerald-500 rounded-full" />
                                        </div>
                                    ) : (
                                        <div className="w-4 h-4 bg-white border border-rose-500 flex items-center justify-center p-0.5">
                                            <div className="w-full h-full bg-rose-500 rounded-full" />
                                        </div>
                                    )}
                                </div>
                                {!product.isAvailable && (
                                    <div className="absolute inset-0 bg-white/80 backdrop-blur-[2px] flex items-center justify-center">
                                        <span className="bg-rose-500 text-white text-[8px] font-black uppercase px-2 py-1 rounded">Out of Stock</span>
                                    </div>
                                )}
                            </div>
                            <div className="flex-1 px-1">
                                <h4 className="text-[11px] font-black text-brand uppercase leading-tight mb-1 line-clamp-2">{product.name}</h4>
                                <div className="text-[9px] font-bold text-brand/40 uppercase tracking-widest mb-2">
                                    {product.hasVariants ? 'From ' : ''}${product.price.toFixed(2)}
                                </div>
                            </div>
                        </button>
                    ))}
                </div>

                {/* Bottom Order Selector (Image 5) */}
                <div className="p-4 bg-white border-t border-brand/5 flex items-center gap-2 flex-shrink-0">
                    {['Default', 'Dine-In', 'Takeaway', 'Delivery'].map(type => (
                        <button
                            key={type}
                            onClick={() => setOrderType(type as OrderChannel)}
                            className={`px-6 py-2 rounded-lg text-xs font-black transition-all border-2 ${orderType === type ? 'bg-brand text-white border-brand' : 'bg-white text-brand border-brand/20 hover:border-brand'}`}
                        >
                            {type}
                        </button>
                    ))}
                </div>
            </main>

            {/* RIGHT: CART & SUMMARY (Image 5 - Dark Theme) */}
            <aside className="w-80 md:w-96 bg-[#2C2E33] flex flex-col flex-shrink-0 text-white shadow-2xl z-20">
                {/* Cart Items */}
                <div className="flex-1 overflow-y-auto custom-scrollbar">
                    {cart?.map(item => (
                        <div key={item.id} className="border-b border-white/5 p-4 flex flex-col group">
                            <div className="flex items-center justify-between mb-2">
                                <div className="flex items-center gap-3 flex-1 min-w-0">
                                    <div className="flex-1 min-w-0">
                                        <h5 className="text-[13px] font-bold truncate tracking-tight uppercase">{item.name}</h5>
                                        {item.variants.length > 0 && (
                                            <p className="text-[10px] text-white/40 font-bold uppercase">
                                                {item.variants.map(v => v.name).join(' • ')}
                                            </p>
                                        )}
                                    </div>
                                </div>
                                <div className="flex items-center gap-4">
                                    <span className="text-[13px] font-bold text-white/60">x {item.quantity}</span>
                                    <span className="text-[13px] font-black w-16 text-right">${(item.price * item.quantity).toFixed(2)}</span>
                                    <button onClick={() => removeFromCart(item.id)} className="text-rose-500 p-2 bg-rose-500/10 rounded-lg">
                                        <X size={14} />
                                    </button>
                                </div>
                            </div>
                            {item.modifiers.length > 0 && (
                                <div className="pl-6 space-y-1">
                                    {item.modifiers.map(mod => (
                                        <div key={mod.optionId} className="flex justify-between text-[9px] font-bold text-white/40 uppercase">
                                            <span>+ {mod.name} (x{mod.quantity})</span>
                                            <span>${(mod.price * mod.quantity).toFixed(2)}</span>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    ))}
                    {(!cart || cart.length === 0) && (
                        <div className="h-full flex flex-col items-center justify-center py-20 text-center opacity-20">
                            <ShoppingCart size={64} className="mb-4" />
                            <p className="text-lg font-black uppercase tracking-[0.2em]">Cart is empty</p>
                        </div>
                    )}
                </div>

                {/* Pricing Summary (Image 5 Footer) */}
                <div className="p-6 bg-[#232529] space-y-4 shadow-t-xl">
                    <div className="flex items-center justify-between mb-2">
                        <button
                            onClick={() => setShowDiscountModal(true)}
                            className="text-[10px] font-black text-amber-400 uppercase tracking-widest flex items-center gap-2 hover:bg-amber-400/10 px-3 py-1 rounded-full transition-all"
                        >
                            <Tag size={12} /> Apply Discount
                        </button>
                        <div className="text-[10px] font-black text-white/20 uppercase tracking-widest">Rules: Standard</div>
                    </div>

                    <div className="grid grid-cols-2 gap-y-2">
                        <div className="text-[11px] font-black text-white/40 uppercase tracking-widest">Subtotal</div>
                        <div className="text-[13px] font-black text-right">{formatCurrency(subtotal)}</div>

                        {appliedDiscount > 0 && (
                            <>
                                <div className="text-[11px] font-black text-emerald-400 uppercase tracking-widest">Discount Applied</div>
                                <div className="text-[13px] font-black text-right text-emerald-400">-{formatCurrency(discountAmount)}</div>
                            </>
                        )}

                        <div className="text-[11px] font-black text-white/40 uppercase tracking-widest">Taxes (SC 10%)</div>
                        <div className="text-[13px] font-black text-right">{formatCurrency(tax)}</div>

                        <div className="text-[11px] font-black text-white/40 uppercase tracking-widest">Round Off</div>
                        <div className="text-[13px] font-black text-right">$0.19</div>
                    </div>

                    <div className="pt-4 border-t border-white/10 flex items-center justify-between">
                        <div>
                            <div className="text-[10px] font-black text-white/40 uppercase tracking-widest mb-1">Items / Quantity</div>
                            <div className="text-lg font-black">{cart?.length || 0} / {cart?.reduce((a, b) => a + b.quantity, 0) || 0}</div>
                        </div>
                        <div className="text-right">
                            <div className="text-[10px] font-black text-white/40 uppercase tracking-widest mb-1">Payable Amount</div>
                            <div className="text-4xl font-black text-white tracking-tighter">{formatCurrency(total)}</div>
                        </div>
                    </div>

                    <div className="grid grid-cols-4 gap-2 pt-2">
                        <button
                            onClick={() => router.push('/pos/dashboard')}
                            className="h-14 bg-white/10 text-white rounded-xl flex items-center justify-center hover:bg-white/20 transition-all"
                        >
                            <ChevronRight className="rotate-180" size={20} />
                        </button>
                        <button
                            onClick={() => setCart([])}
                            className="h-14 bg-rose-500/10 text-rose-500 rounded-xl flex items-center justify-center hover:bg-rose-500 hover:text-white transition-all"
                        >
                            <Trash2 size={20} />
                        </button>
                        <button className="h-14 bg-amber-500/10 text-amber-500 rounded-xl flex items-center justify-center hover:bg-amber-500 hover:text-white transition-all">
                            <Pause size={20} />
                        </button>
                        <button
                            onClick={() => setShowSuccess(true)}
                            className="h-14 bg-emerald-600 text-white rounded-xl flex-1 col-span-1 min-w-[120px] font-black text-xs uppercase tracking-widest flex items-center justify-center gap-2 shadow-xl shadow-emerald-500/20 active:scale-95 transition-all"
                        >
                            Save Order
                        </button>
                    </div>
                    <button
                        onClick={() => router.push('/pos/payment')}
                        className="w-full h-16 bg-brand text-white rounded-xl font-black text-sm uppercase tracking-[0.2em] shadow-xl shadow-white/5 active:scale-95 transition-all flex items-center justify-center gap-3"
                    >
                        Proceed to Payment
                        <ArrowRight size={20} />
                    </button>
                </div>
            </aside>

            {/* PRODUCT CUSTOMIZATION MODAL (Section 6) */}
            {selectedProduct && (
                <div className="fixed inset-0 bg-brand/40 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
                    <div className="bg-white w-full max-w-4xl rounded-[3rem] shadow-2xl overflow-hidden border-4 border-brand/10 flex flex-col max-h-[95vh] animate-in zoom-in duration-300">
                        <div className="p-8 border-b border-brand/10 flex items-center justify-between bg-brand/5">
                            <div className="flex items-center gap-6">
                                <div className="w-20 h-20 bg-white rounded-3xl overflow-hidden shadow-lg p-1 border border-brand/10">
                                    <img src={selectedProduct.image} className="w-full h-full object-cover rounded-2xl" />
                                </div>
                                <div>
                                    <h3 className="text-3xl font-black text-brand tracking-tight uppercase">{selectedProduct.name}</h3>
                                    <div className="flex items-center gap-3 mt-1">
                                        <div className="px-3 py-1 bg-brand/10 text-brand text-[9px] font-black uppercase tracking-widest rounded-full">Base: ${selectedProduct.price.toFixed(2)}</div>
                                        <div className="w-1.5 h-1.5 rounded-full bg-brand/20" />
                                        <div className="text-brand/40 text-[9px] font-black uppercase tracking-widest">SKU: {selectedProduct.sku}</div>
                                    </div>
                                </div>
                            </div>
                            <button onClick={() => setSelectedProduct(null)} className="w-14 h-14 bg-white border border-brand/10 rounded-2xl flex items-center justify-center text-brand/40 hover:text-brand transition-all shadow-sm">
                                <X size={28} />
                            </button>
                        </div>

                        <div className="flex-1 flex overflow-hidden">
                            {/* Left Config Panel */}
                            <div className="flex-1 overflow-y-auto p-10 space-y-12 custom-scrollbar">
                                {/* Combo Builder (Section 6.3) */}
                                {selectedProduct.isCombo && selectedProduct.comboSlots && (
                                    <section>
                                        <div className="flex items-center gap-2 mb-6">
                                            <div className="w-8 h-8 bg-brand rounded-lg flex items-center justify-center text-white">
                                                <ListIcon size={16} />
                                            </div>
                                            <h4 className="text-xs font-black text-brand uppercase tracking-[0.2em]">Combo Builder</h4>
                                        </div>
                                        <div className="grid grid-cols-2 gap-4">
                                            {selectedProduct.comboSlots.map(slot => (
                                                <button
                                                    key={slot.id}
                                                    onClick={() => setActiveComboSlot(slot.id)}
                                                    className={`p-6 rounded-[2rem] border-4 text-left transition-all ${activeComboSlot === slot.id ? 'bg-brand border-brand text-white shadow-xl' : 'bg-brand/5 border-transparent text-brand hover:bg-brand/10'}`}
                                                >
                                                    <div className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-60">{slot.name}</div>
                                                    <div className="text-sm font-black truncate">
                                                        {comboSelections[slot.id]?.name || 'Select Item...'}
                                                    </div>
                                                </button>
                                            ))}
                                        </div>

                                        {/* Slot Item Selector */}
                                        {activeComboSlot && (
                                            <div className="mt-8 p-8 bg-brand/5 rounded-[2.5rem] border border-brand/10">
                                                <h5 className="text-[10px] font-black uppercase tracking-widest mb-6 text-brand/40">Choose {selectedProduct.comboSlots.find(s => s.id === activeComboSlot)?.name}</h5>
                                                <div className="grid grid-cols-2 gap-3 max-h-60 overflow-y-auto pr-2 custom-scrollbar">
                                                    {mockPOSProducts
                                                        .filter(p => selectedProduct.comboSlots?.find(s => s.id === activeComboSlot)?.allowedCategoryIds.includes(p.categoryId))
                                                        .map(p => (
                                                            <button
                                                                key={p.id}
                                                                onClick={() => setComboSelections({
                                                                    ...comboSelections, [activeComboSlot]: {
                                                                        id: p.id,
                                                                        productId: p.id,
                                                                        name: p.name,
                                                                        price: p.price,
                                                                        quantity: 1,
                                                                        variants: [],
                                                                        modifiers: []
                                                                    }
                                                                })}
                                                                className={`p-4 rounded-2xl border-2 transition-all text-left flex items-center gap-3 ${comboSelections[activeComboSlot]?.productId === p.id ? 'bg-brand border-brand text-white shadow-lg' : 'bg-white border-brand/5 text-brand hover:border-brand/20'}`}
                                                            >
                                                                <div className="w-10 h-10 rounded-xl overflow-hidden flex-shrink-0">
                                                                    <img src={p.image} className="w-full h-full object-cover" />
                                                                </div>
                                                                <div className="text-[11px] font-black uppercase leading-tight">{p.name}</div>
                                                            </button>
                                                        ))
                                                    }
                                                </div>
                                            </div>
                                        )}
                                    </section>
                                )}

                                {/* Variants (Section 6.1) */}
                                {selectedProduct.variantGroups?.map(group => (
                                    <section key={group.id}>
                                        <div className="flex items-center gap-2 mb-6">
                                            <div className="w-8 h-8 bg-brand rounded-lg flex items-center justify-center text-white font-black text-[10px]">
                                                {group.name.charAt(0)}
                                            </div>
                                            <h4 className="text-xs font-black text-brand uppercase tracking-[0.2em]">{group.name}</h4>
                                        </div>
                                        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                                            {group.options.map(opt => (
                                                <button
                                                    key={opt.id}
                                                    onClick={() => setSelectedVariants({ ...selectedVariants, [group.id]: opt.id })}
                                                    className={`py-6 px-4 rounded-3xl border-2 text-center transition-all ${selectedVariants[group.id] === opt.id ? 'bg-brand border-brand text-white shadow-xl scale-105 z-10' : 'bg-white border-brand/5 text-brand hover:border-brand/20'}`}
                                                >
                                                    <div className="text-[11px] font-black uppercase tracking-widest">{opt.name}</div>
                                                    {opt.additionalPrice > 0 && (
                                                        <div className={`text-[9px] font-bold uppercase mt-1 ${selectedVariants[group.id] === opt.id ? 'text-white/60' : 'text-brand/40'}`}>
                                                            +${opt.additionalPrice.toFixed(2)}
                                                        </div>
                                                    )}
                                                </button>
                                            ))}
                                        </div>
                                    </section>
                                ))}

                                {/* Modifiers (Section 6.2) */}
                                {selectedProduct.modifierGroups?.map(group => (
                                    <section key={group.id}>
                                        <div className="flex items-center gap-2 mb-6">
                                            <div className="w-8 h-8 bg-brand rounded-lg flex items-center justify-center text-white">
                                                <Plus size={16} />
                                            </div>
                                            <h4 className="text-xs font-black text-brand uppercase tracking-[0.2em]">{group.name}</h4>
                                        </div>
                                        <div className="grid grid-cols-2 gap-4">
                                            {group.options.map(opt => {
                                                const current = selectedModifiers[opt.id]?.quantity || 0;
                                                return (
                                                    <div
                                                        key={opt.id}
                                                        className={`p-6 rounded-[2rem] border-2 flex items-center justify-between transition-all ${current > 0 ? 'bg-brand/5 border-brand' : 'bg-white border-brand/5'}`}
                                                    >
                                                        <div className="text-left">
                                                            <div className="text-[11px] font-black uppercase tracking-widest text-brand">{opt.name}</div>
                                                            <div className="text-[9px] font-bold text-brand/40 uppercase tracking-widest">+${opt.price.toFixed(2)}</div>
                                                        </div>
                                                        <div className="flex items-center gap-4">
                                                            <button
                                                                onClick={() => {
                                                                    if (current > 0) {
                                                                        const next = { ...selectedModifiers };
                                                                        if (current === 1) delete next[opt.id];
                                                                        else next[opt.id] = { ...next[opt.id], quantity: current - 1 };
                                                                        setSelectedModifiers(next);
                                                                    }
                                                                }}
                                                                className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${current > 0 ? 'bg-white text-brand shadow-sm' : 'bg-brand/5 text-brand/20'}`}
                                                            >
                                                                <Minus size={16} />
                                                            </button>
                                                            <span className="w-4 text-center text-sm font-black text-brand">{current}</span>
                                                            <button
                                                                onClick={() => {
                                                                    setSelectedModifiers({
                                                                        ...selectedModifiers,
                                                                        [opt.id]: { name: opt.name, price: opt.price, quantity: current + 1 }
                                                                    });
                                                                }}
                                                                className="w-10 h-10 bg-brand text-white rounded-xl flex items-center justify-center shadow-lg shadow-brand/20"
                                                            >
                                                                <Plus size={16} />
                                                            </button>
                                                        </div>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </section>
                                ))}
                            </div>

                            {/* Right Summary Sidebar (Customization) */}
                            <div className="w-96 bg-brand/5 border-l border-brand/10 flex flex-col p-10">
                                <h4 className="text-xs font-black text-brand uppercase tracking-[0.2em] mb-8">Selected Options</h4>
                                <div className="flex-1 overflow-y-auto space-y-4 custom-scrollbar">
                                    {/* Summary List */}
                                    {Object.entries(selectedVariants).map(([gid, oid]) => {
                                        const group = selectedProduct.variantGroups?.find(g => g.id === gid);
                                        const opt = group?.options.find(o => o.id === oid);
                                        return (opt && (
                                            <div key={gid} className="flex justify-between text-[11px] font-bold uppercase text-brand tracking-widest">
                                                <span className="opacity-40">{group?.name}:</span>
                                                <span>{opt.name}</span>
                                            </div>
                                        ));
                                    })}
                                    <div className="h-px bg-brand/10 my-4" />
                                    {Object.values(selectedModifiers).map(mod => (
                                        <div key={mod.name} className="flex justify-between text-[11px] font-bold uppercase text-brand tracking-widest">
                                            <span>{mod.name} (x{mod.quantity})</span>
                                            <span>+${(mod.price * mod.quantity).toFixed(2)}</span>
                                        </div>
                                    ))}
                                    {selectedProduct.isCombo && Object.values(comboSelections).map(sel => (
                                        <div key={sel.productId} className="flex justify-between text-[11px] font-bold uppercase text-brand tracking-widest">
                                            <span className="text-emerald-600">INCL: {sel.name}</span>
                                            <Check size={12} className="text-emerald-600" />
                                        </div>
                                    ))}
                                </div>

                                <div className="pt-8 border-t border-brand/10 space-y-6">
                                    <div className="flex justify-between items-end">
                                        <div className="text-[10px] font-black uppercase tracking-widest text-brand/40">Total Price</div>
                                        <div className="text-4xl font-black text-brand tracking-tighter">${currentCustomPrice.toFixed(2)}</div>
                                    </div>
                                    <button
                                        onClick={handleAddCustomized}
                                        className="w-full py-6 bg-brand text-white rounded-3xl font-black text-[10px] uppercase tracking-[0.3em] shadow-xl shadow-brand/20 active:scale-95 transition-all"
                                    >
                                        Add to Order Ticket
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* SUCCESS MODAL (Image 4) */}
            {showSuccess && (
                <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
                    <div className="bg-white rounded-[2.5rem] p-12 max-w-sm w-full shadow-2xl animate-in zoom-in duration-300 flex flex-col items-center text-center">
                        <div className="w-24 h-24 bg-emerald-500/10 rounded-full flex items-center justify-center mb-6 ring-8 ring-emerald-500/5">
                            <div className="w-20 h-20 bg-emerald-500 rounded-full flex items-center justify-center text-white shadow-lg shadow-emerald-500/40">
                                <Check size={48} />
                            </div>
                        </div>
                        <h2 className="text-4xl font-black text-brand tracking-tight mb-8">Success!</h2>
                        <button
                            onClick={() => { setShowSuccess(false); setCart([]); router.push('/pos/dashboard'); }}
                            className="w-full py-4 bg-white border-4 border-amber-400 text-brand rounded-xl font-black text-sm uppercase tracking-widest hover:bg-amber-400 hover:text-white transition-all shadow-lg"
                        >
                            Ok
                        </button>
                    </div>
                </div>
            )}

            <POSDiscountModal
                isOpen={showDiscountModal}
                onClose={() => setShowDiscountModal(false)}
                onApply={(type, val) => {
                    if (type === 'PERCENT') setAppliedDiscount(val / 100);
                    else setAppliedDiscount(val);
                    setShowDiscountModal(false);
                }}
            />

            <POSQuickSettings
                isOpen={showQuickSettings}
                onClose={() => setShowQuickSettings(false)}
            />
        </div>
    );
};

const ListIcon = ({ size, className }: { size?: number, className?: string }) => (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className={className}>
        <line x1="8" y1="6" x2="21" y2="6" /><line x1="8" y1="12" x2="21" y2="12" /><line x1="8" y1="18" x2="21" y2="18" /><line x1="3" y1="6" x2="3.01" y2="6" /><line x1="3" y1="12" x2="3.01" y2="12" /><line x1="3" y1="18" x2="3.01" y2="18" />
    </svg>
);
